def evens(n):
    i = 0
    while i < n:
        yield i
        i += 2
def double(gen):
    for v in gen:
        yield v * 2
def take(gen, k):
    cnt = 0
    for v in gen:
        if cnt >= k:
            return
        yield v
        cnt += 1
print(list(evens(7)))
print(list(double(evens(5))))
print(list(take(double(evens(10)), 3)))

def flatten(x):
    out = []
    for item in x:
        if isinstance(item, list):
            for sub in flatten(item):
                out.append(sub)
        else:
            out.append(item)
    return out
